WITH unpacked AS (SELECT id, plan, currency, tier_prices, SLICE(tier_limits, 1, 2) AS first_two_limits, ELEMENT_AT(tier_prices, 1) AS entry_price, ARRAY_MIN(tier_prices) AS lowest_price, AGGREGATE(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price FROM price_tiers) SELECT *, ROW_NUMBER() OVER (ORDER BY entry_price DESC, id) row_seq, PERCENT_RANK() OVER (PARTITION BY plan ORDER BY avg_tier_price) avg_tier_price_percent_rank, NTILE(5) OVER (PARTITION BY plan ORDER BY avg_tier_price DESC, id) avg_tier_price_bucket FROM unpacked WHERE entry_price > 14;
